/* C API of the Rust port of `gcd.c`, generated by rust-anything. */
#ifndef GCD_RS_H
#define GCD_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

unsigned long gcd(unsigned long a, unsigned long b);

/* The same functions under `rust_anything_` names, for shadow runs. */
unsigned long rust_anything_gcd(unsigned long a, unsigned long b);

#endif /* GCD_RS_H */
